
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_xc_kt2_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_xc_kt2", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.791661284842897e+00, -4.706064881485082e+00, -4.586402601520708e+00, -4.421235587215413e+00, -4.197457848062123e+00, -3.902433084506765e+00, -3.528932994146986e+00, -3.084267218098875e+00, -2.602350646849917e+00, -2.130818867075516e+00, -1.511036000438679e+00, -8.003798334622724e-01, -6.787095518897841e-01, -5.577782722218427e-01, -3.850421826684842e-01, -2.189489742929451e-01, -1.010036025029496e-01, -3.476240277401957e-02, -7.748665255330498e-03, -9.071481763352604e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


